mapper.select:
SELECT product_id, property_value_id_hash, stock
FROM sku_stock
WHERE product_id = #{productId}
  AND property_value_id_hash = #{propertyValueIdHash}

SELECT product_id, property_value_id_hash, stock
FROM sku_stock
WHERE product_id = #{productId}
  AND property_value_id_hash = #{propertyValueIdHash}
FOR UPDATE

mapper.update:
UPDATE sku_stock
SET stock = stock + #{changeAmount}
WHERE product_id = #{productId}
  AND property_value_id_hash = #{propertyValueIdHash}
  AND stock + #{changeAmount} >= 0

mapper.insert:
INSERT INTO sku_stock (product_id, property_value_id_hash, stock)
VALUES (#{productId}, #{propertyValueIdHash}, #{stock})
ON DUPLICATE KEY UPDATE stock = #{stock}

mapper.select:
SELECT COALESCE(SUM(stock), 0)
FROM sku_stock
WHERE product_id = #{productId}

SELECT product_id AS productId, COALESCE(SUM(stock), 0) AS totalStock FROM sku_stock WHERE product_id IN
#{item}
GROUP BY product_id

SELECT COUNT(1)
FROM sku_stock
WHERE stock < #{threshold}

SELECT product_id, property_value_id_hash, stock
FROM sku_stock
WHERE stock < #{threshold}
ORDER BY stock ASC, product_id ASC, property_value_id_hash ASC
LIMIT #{offset}, #{limit}
